const liczby = [4, 1, 7, 2];
liczby.sort(function (a, b) { return a - b; });
console.log(liczby); // [1, 2, 4, 7]

const liczby = [4, 1, 7, 2];
liczby.sort((a, b) => a - b);
console.log(liczby); // [1, 2, 4, 7]

const suma = (function () {
  return 5 + 7;
})();

console.log(suma); // 12

(function () {
  const pomocnicza = "tylko wewnatrz IIFE";
  console.log(pomocnicza); // dziala wewnatrz
})();

// console.log(pomocnicza); // ReferenceError: pomocnicza is not defined
// zmienna pomocnicza istnieje WYLACZNIE wewnatrz zasiegu IIFE,
// dokladnie jak kazda inna zmienna lokalna funkcji (rozdzial 1)

(() => {
  console.log("IIFE dziala!");
})();

const zwierzeta = ["kot", "pies", "chomik"];
zwierzeta.forEach((slowo, indeks) => {
